// 1. Define typical STM32 Internal Sensor calibration constants
const V_AT_25C = 0.76;      // Volts at 25°C
const AVG_SLOPE = 0.0025;   // 2.5 mV/°C converted to Volts/°C

// 2. Generate highly realistic MCU Mock Data (Assuming 12-bit ADC: 0-4095)
let ADC1IN1 = Math.floor(Math.random() * (2600 - 1500) + 1500); 
let BLUELED = Math.round(Math.random());                        
let VREFINT = Math.floor(Math.random() * (1700 - 1600) + 1600); 

// Dynamically calculate actual operational VDDA (v_ref) based on the VREFINT reading
let v_ref = (1.21 * 4095) / VREFINT; 

// Calculate actual analog voltage on target pin
let voltage1 = (ADC1IN1 * v_ref) / 4095;

// Internal temperature sensor raw ADC reading typically scales between 900-1100
let TEMPSENSOR = Math.floor(Math.random() * (1100 - 950) + 950); 
let v_sense = (TEMPSENSOR * v_ref) / 4095;

// Linear formula to extract actual Celsius degrees from analog sensor voltage step
let temp = ((v_sense - V_AT_25C) / AVG_SLOPE) + 25.0; 

// 3. Format floats and build the clean JSON payload object
msg.payload = {
    "ADC1IN1": ADC1IN1,
    "voltage1": Number(voltage1.toFixed(4)),
    "BLUELED": BLUELED,
    "TEMPSENSOR": TEMPSENSOR,
    "v_ref": Number(v_ref.toFixed(4)),
    "v_sense": Number(v_sense.toFixed(4)),
    "temp": Number(temp.toFixed(2)),
    "VREFINT": VREFINT
};

// Set a descriptive topic for your telemetry stream
msg.topic = "telemetry/mcu_mock_data";

return msg;

